HASHES={'build_ext_bank.py': 'e773ced7f9d57f3f5c7dc674b92b6ab0af03893f5f33e22c9d83b5edba88e19a', 'series_inventory.csv': 'e7a3950acc292ec865977ab74e2c434368abaa866a72696ed5fdb6d14b92ce0a', 'reference_manifest.csv': '283317f7f1938d86fff56a52bc1c4a3312f550d8f629c0cd26788436d250f0ae', 'contact_parents30.csv': '26bdc2ba65cfe687632e07f1efd156d5cffeaea5ef2cd1f1af8b1a302d63eb89'}
for name,blob in BLOBS.items():
    data=zlib.decompress(base64.b85decode(blob))
    if hashlib.sha256(data).hexdigest()!=HASHES[name]:raise RuntimeError(name)
    (work/name).write_bytes(data)
roots=sorted({p.parent for p in Path('/kaggle/input').rglob('ASSET_MANIFEST.json')})
if len(roots)!=1:raise RuntimeError(f'Expected one asset root: {roots}')
asset=roots[0]
if hashlib.sha256((asset/'ASSET_MANIFEST.json').read_bytes()).hexdigest()!='4c4ea47cb2328fd8812b6f580a27327072e560bec457d5bde970f7f293c7079c':raise RuntimeError('Asset manifest drift')
manifest=json.loads((asset/'ASSET_MANIFEST.json').read_text())
for rec in manifest['files']:
    p=asset/rec['path']
    if p.stat().st_size!=rec['bytes'] or hashlib.sha256(p.read_bytes()).hexdigest()!=rec['sha256']:
        raise RuntimeError(f'Asset drift: {rec["path"]}')
comp=[p.parent for p in Path('/kaggle/input').rglob('train_series.csv') if (p.parent/'train_series').is_dir()]
if len(comp)!=1:raise RuntimeError(f'Expected one competition: {comp}')
comp=comp[0]
sys.argv=['build_ext_bank.py','--runtime',str(asset/'orientation_runtime/runtime'),
    '--series-csv',str(comp/'train_series.csv'),'--inventory',str(work/'series_inventory.csv'),
    '--output','/kaggle/working/k24_allseries_ext_s04',
    '--cohort','train','--images-root',str(comp/'train_series'),
    '--training-manifest',str(asset/'training_overlay_soft_v2/training_manifest4352.csv'),
    '--operations',str(asset/'training_overlay_soft_v2/series_operations.csv'),
    '--parent-shards',str(asset/'manifests/parent_shards16.csv'),'--shard','4',
    '--reference-manifest',str(work/'reference_manifest.csv'),
    '--parity-parents',str(asset/'manifests/smoke_train_parents200.csv'),
    '--contact-parents',str(work/'contact_parents30.csv'),'--threads','4']
runpy.run_path(str(work/'build_ext_bank.py'),run_name='__main__')
